import {
  cloneVNode,
  defineComponent,
  h,
  isVNode,
  Fragment,
  mergeProps,
  shallowRef,
  watch,
  type PropType,
  type Ref,
  type VNode,
} from 'vue';
import {
  animate,
  cancelFrame,
  frame,
  motionValue,
  type MotionValue,
  type Transition,
} from 'motion-v';

import { screenScale } from '../../../internal/screen-scale';
import {
  motionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';

const SETTLE = motionTokens.transition.fade;

type ScrollFadeOrientation = 'vertical' | 'horizontal' | 'both';

type ScrollFadeEdge = 'top' | 'bottom' | 'left' | 'right';

type UseScrollFadeOptions = {
  orientation?: ScrollFadeOrientation;
  size?: number;
  shrink?: number;
  blur?: number;
  transition?: Transition;
  enabled?: boolean;
};

type ScrollFadeValues = Record<ScrollFadeEdge, MotionValue<number>>;

const EDGES: ScrollFadeEdge[] = ['top', 'bottom', 'left', 'right'];

const VAR = {
  top: '--scroll-fade-top',
  bottom: '--scroll-fade-bottom',
  left: '--scroll-fade-left',
  right: '--scroll-fade-right',
  size: '--scroll-fade-size',
} as const;

const edgeStop = (edge: ScrollFadeEdge) =>
  `rgb(0 0 0 / calc(1 - var(${VAR[edge]}, 0)))`;
const depth = (edge: ScrollFadeEdge) =>
  `calc(var(${VAR.size}) * min(1, var(${VAR[edge]}, 0) * 1000))`;

const GRADIENT_Y = `linear-gradient(to bottom, ${edgeStop('top')} 0, #000 ${depth('top')}, #000 calc(100% - ${depth('bottom')}), ${edgeStop('bottom')} 100%)`;
const GRADIENT_X = `linear-gradient(to right, ${edgeStop('left')} 0, #000 ${depth('left')}, #000 calc(100% - ${depth('right')}), ${edgeStop('right')} 100%)`;

const MASKS: Record<ScrollFadeOrientation, string> = {
  vertical: GRADIENT_Y,
  horizontal: GRADIENT_X,
  both: `${GRADIENT_Y}, ${GRADIENT_X}`,
};

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const smooth = (value: number) => value * value * (3 - 2 * value);

const ZONE = 1.75;
const GESTURE_GAP = 150;

type ItemSlot = { item: HTMLElement; x: number; y: number; ownFilter: boolean };

const GROUP = 'ul, ol, [role="list"], [role="group"]';

function collectItems(parent: Element, items: HTMLElement[]) {
  for (const child of parent.children) {
    if (!(child instanceof HTMLElement)) continue;
    const isGroup =
      child.matches(GROUP) ||
      Array.from(child.children).some((inner) => inner.matches(GROUP));
    if (isGroup) collectItems(child, items);
    else items.push(child);
  }
  return items;
}

function itemsOf(el: HTMLElement) {
  let parent: Element = el;
  while (parent.children.length === 1) parent = parent.children[0]!;
  return collectItems(parent, []);
}

function setMask(el: HTMLElement, mask: string | null) {
  const style = el.style;
  if (mask) {
    style.setProperty('mask-image', mask);
    style.setProperty('-webkit-mask-image', mask);
    style.setProperty('mask-composite', 'intersect');
    style.setProperty('-webkit-mask-composite', 'source-in');
  } else {
    for (const property of [
      'mask-image',
      '-webkit-mask-image',
      'mask-composite',
      '-webkit-mask-composite',
    ])
      style.removeProperty(property);
  }
}

/** Fades (and shrinks, and blurs) the edges where a scroll area overflows. */
function useScrollFade(
  element: Ref<HTMLElement | null>,
  options: () => UseScrollFadeOptions = () => ({}),
): ScrollFadeValues {
  const reduce = useShouldReduceMotion();
  const settle = useTempoTransition(() => options().transition ?? SETTLE);
  const values: ScrollFadeValues = {
    top: motionValue(0),
    bottom: motionValue(0),
    left: motionValue(0),
    right: motionValue(0),
  };

  watch(
    () => {
      const o = options();
      return [
        element.value,
        o.enabled ?? true,
        o.orientation ?? 'vertical',
        o.size ?? 40,
        o.shrink ?? 0.03,
        o.blur ?? 4,
      ] as const;
    },
    ([el, enabled, orientation, size, shrink, blur], _, onCleanup) => {
      if (!el || !enabled) return;
      const vertical = orientation !== 'horizontal';
      const horizontal = orientation !== 'vertical';
      const mask = MASKS[orientation];
      let masked = false;

      el.style.setProperty(VAR.size, `${size}px`);

      const shrunk = new Set<HTMLElement>();
      const blurred = new Set<HTMLElement>();
      const restore = () => {
        for (const item of shrunk) item.style.removeProperty('scale');
        for (const item of blurred) item.style.removeProperty('filter');
        shrunk.clear();
        blurred.clear();
      };

      let slots: ItemSlot[] = [];
      let width = 0;
      let height = 0;
      const measureItems = () => {
        if (!shrink && !blur) {
          slots = [];
          return;
        }
        const box = el.getBoundingClientRect();
        const [sx, sy] = screenScale(el);
        width = el.clientWidth;
        height = el.clientHeight;
        slots = itemsOf(el).map((item) => {
          const rect = item.getBoundingClientRect();
          return {
            item,
            x: (rect.left + rect.width / 2 - box.left) / sx + el.scrollLeft,
            y: (rect.top + rect.height / 2 - box.top) / sy + el.scrollTop,
            ownFilter:
              !blurred.has(item) && getComputedStyle(item).filter !== 'none',
          };
        });
      };

      const zone = size * ZONE;
      const reach = (distance: number) =>
        zone > 0 ? smooth(clamp01(1 - distance / zone)) : 0;

      let dirty = true;
      const paintItems = () => {
        if (dirty) {
          dirty = false;
          measureItems();
        }
        const scale = reduce.value ? 0 : shrink;
        if (!slots.length || (!scale && !blur)) return restore();
        const scrollX = el.scrollLeft;
        const scrollY = el.scrollTop;
        for (const { item, x, y, ownFilter } of slots) {
          let depth = 0;
          if (vertical) {
            const center = y - scrollY;
            depth = Math.max(
              reach(center) * values.top.get(),
              reach(height - center) * values.bottom.get(),
            );
          }
          if (horizontal) {
            const center = x - scrollX;
            depth = Math.max(
              depth,
              reach(center) * values.left.get(),
              reach(width - center) * values.right.get(),
            );
          }
          if (depth > 0.001 && scale) {
            item.style.scale = String(1 - scale * depth);
            shrunk.add(item);
          } else if (shrunk.delete(item)) item.style.removeProperty('scale');
          if (depth > 0.001 && blur && !ownFilter) {
            item.style.filter = `blur(${(blur * depth).toFixed(2)}px)`;
            blurred.add(item);
          } else if (blurred.delete(item)) item.style.removeProperty('filter');
        }
      };

      let scheduled = false;
      const runPaint = () => {
        scheduled = false;
        paintItems();
      };
      const shrinkItems = () => {
        if (scheduled) return;
        scheduled = true;
        frame.render(runPaint);
      };

      const write = () => {
        let any = false;
        for (const edge of EDGES) {
          const amount = clamp01(values[edge].get());
          if (amount > 0.001) any = true;
          el.style.setProperty(VAR[edge], amount.toFixed(4));
        }
        if (any !== masked) {
          masked = any;
          setMask(el, any ? mask : null);
        }
        shrinkItems();
      };

      const unsubscribe = EDGES.map((edge) => values[edge].on('change', write));

      const ramp = size / 2;
      const amount = (distance: number) =>
        ramp > 0 ? clamp01(distance / ramp) : distance > 0.5 ? 1 : 0;

      const measure = (follow: boolean) => {
        const targets: Record<ScrollFadeEdge, number> = {
          top: 0,
          bottom: 0,
          left: 0,
          right: 0,
        };

        if (vertical) {
          const max = el.scrollHeight - el.clientHeight;
          if (max > 1) {
            targets.top = amount(el.scrollTop);
            targets.bottom = amount(max - el.scrollTop);
          }
        }

        if (horizontal) {
          const max = el.scrollWidth - el.clientWidth;
          if (max > 1) {
            const fromStart = Math.abs(el.scrollLeft);
            const fromEnd = max - fromStart;
            const rtl = getComputedStyle(el).direction === 'rtl';
            targets.left = amount(rtl ? fromEnd : fromStart);
            targets.right = amount(rtl ? fromStart : fromEnd);
          }
        }

        for (const edge of EDGES) {
          if (follow || reduce.value) values[edge].jump(targets[edge]);
          else if (Math.abs(values[edge].get() - targets[edge]) > 0.001)
            animate(values[edge], targets[edge], settle.value);
        }
        write();
      };

      measure(true);

      let lastScroll = 0;
      const onScroll = () => {
        const now = performance.now();
        if (now - lastScroll > GESTURE_GAP) dirty = true;
        lastScroll = now;
        measure(true);
      };
      el.addEventListener('scroll', onScroll, { passive: true });

      const resizeObserver = new ResizeObserver(() => {
        dirty = true;
        measure(false);
      });
      const observeChildren = () => {
        resizeObserver.disconnect();
        resizeObserver.observe(el);
        for (const child of el.children) resizeObserver.observe(child);
      };
      observeChildren();
      const mutationObserver = new MutationObserver((records) => {
        if (records.some((record) => record.target === el)) observeChildren();
        dirty = true;
        measure(false);
      });
      mutationObserver.observe(el, { childList: true, subtree: true });

      onCleanup(() => {
        el.removeEventListener('scroll', onScroll);
        cancelFrame(runPaint);
        resizeObserver.disconnect();
        mutationObserver.disconnect();
        unsubscribe.forEach((off) => off());
        setMask(el, null);
        restore();
        for (const name of Object.values(VAR)) el.style.removeProperty(name);
        for (const edge of EDGES) values[edge].jump(0);
      });
    },
    { flush: 'post', immediate: true },
  );

  return values;
}

type ScrollFadeProps = UseScrollFadeOptions & { asChild?: boolean };

const OVERFLOW: Record<ScrollFadeOrientation, Record<string, string>> = {
  vertical: { overflowY: 'auto' },
  horizontal: { overflowX: 'auto' },
  both: { overflow: 'auto' },
};

function firstElement(nodes: VNode[] | undefined): VNode | null {
  for (const node of nodes ?? []) {
    if (!isVNode(node)) continue;
    if (node.type === Fragment && Array.isArray(node.children)) {
      const inner = firstElement(node.children as VNode[]);
      if (inner) return inner;
    } else if (typeof node.type !== 'symbol') return node;
  }
  return null;
}

const elementOf = (node: unknown) => {
  const el = (node as { $el?: unknown } | null)?.$el ?? node;
  return el instanceof HTMLElement ? el : null;
};

/** A scroll area whose overflowing edges fade out. */
const ScrollFade = defineComponent({
  name: 'ScrollFade',
  inheritAttrs: false,
  props: {
    asChild: Boolean,
    orientation: {
      type: String as PropType<ScrollFadeOrientation>,
      default: 'vertical',
    },
    size: Number,
    shrink: Number,
    blur: Number,
    transition: Object as PropType<Transition>,
    enabled: { type: Boolean, default: true },
  },
  setup(props, { attrs, slots }) {
    const element = shallowRef<HTMLElement | null>(null);
    useScrollFade(element, () => ({
      orientation: props.orientation,
      size: props.size,
      shrink: props.shrink,
      blur: props.blur,
      transition: props.transition,
      enabled: props.enabled,
    }));
    const ref = (node: unknown) => {
      element.value = elementOf(node);
    };
    return () => {
      const shared = {
        'data-slot': 'scroll-fade',
        'data-orientation': props.orientation,
      };
      if (props.asChild) {
        const child = firstElement(slots.default?.());
        if (child) {
          const { style, ...rest } = attrs;
          return cloneVNode(
            child,
            mergeProps(shared, rest, {
              style: [OVERFLOW[props.orientation], child.props?.style, style],
              ref,
            }),
            true,
          );
        }
      }
      return h(
        'div',
        {
          ...shared,
          ...attrs,
          ref,
          style: [OVERFLOW[props.orientation], attrs.style],
        },
        slots.default?.(),
      );
    };
  },
});

export {
  ScrollFade,
  useScrollFade,
  type ScrollFadeProps,
  type ScrollFadeOrientation,
  type ScrollFadeValues,
  type UseScrollFadeOptions,
};

function screenScale(element: Element | null): [number, number] {
  if (!(element instanceof HTMLElement)) return [1, 1];
  const rect = element.getBoundingClientRect();
  const ratio = (drawn: number, laid: number) =>
    laid && Math.abs(drawn - laid) >= 1 ? drawn / laid : 1;
  return [
    ratio(rect.width, element.offsetWidth),
    ratio(rect.height, element.offsetHeight),
  ];
}

function layoutHeight(element: HTMLElement) {
  const drawn = element.getBoundingClientRect().height || 0;
  return drawn / screenScale(element)[1];
}

export { layoutHeight, screenScale };

import {
  computed,
  defineComponent,
  Fragment,
  getCurrentInstance,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from 'vue';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  spring as springGenerator,
  useMotionConfig,
  type Transition,
} from 'motion-v';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  value: T,
  tempo: number,
): T {
  if (!value || tempo === 1 || typeof value !== 'object') return value;
  const scaled: Record<string, unknown> = {};
  for (const [key, part] of Object.entries(value)) {
    if (typeof part === 'number' && TIME_KEYS.includes(key))
      scaled[key] = part * tempo;
    else if (typeof part === 'number' && key === 'stiffness')
      scaled[key] = part / (tempo * tempo);
    else if (typeof part === 'number' && key === 'damping')
      scaled[key] = part / tempo;
    else if (part && typeof part === 'object' && !Array.isArray(part))
      scaled[key] = scaleTransition(part as Transition, tempo);
    else scaled[key] = part;
  }
  return scaled as T;
}

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;
type CheckAnimation = 'draw' | 'pop';
type ReducedMotion = 'user' | 'never' | 'always';

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensKey: InjectionKey<Ref<MotionTokens>> = Symbol(
  'AnimateUIMotionTokens',
);
const CheckAnimationKey: InjectionKey<Ref<CheckAnimation>> = Symbol(
  'AnimateUICheckAnimation',
);
const ReducedMotionKey: InjectionKey<Ref<ReducedMotion>> = Symbol(
  'AnimateUIReducedMotion',
);

function useMotionTokens(): Ref<MotionTokens> {
  return inject(MotionTokensKey, ref(motionTokens) as Ref<MotionTokens>);
}

/** Scales a transition by the provider's `tempo`. */
function useTempoTransition<T extends Transition | undefined>(
  value: () => T,
): ComputedRef<T> {
  const tokens = useMotionTokens();
  return computed(() => scaleTransition(value(), tokens.value.tempo));
}

function useCheckAnimation(own?: () => CheckAnimation | undefined) {
  const inherited = inject(CheckAnimationKey, ref<CheckAnimation>('draw'));
  return computed(() => own?.() ?? inherited.value);
}

function useReducedMotionSetting(): ComputedRef<ReducedMotion> {
  const own = inject(ReducedMotionKey, ref<ReducedMotion>('user'));
  const config = useMotionConfig();
  return computed(() =>
    config.value.reducedMotion === 'always' ? 'always' : own.value,
  );
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

// Once the app has mounted (hydrated), later components read the setting at once.
const appMounted = () =>
  Boolean(
    (
      getCurrentInstance()?.appContext.app as
        { _container?: unknown } | undefined
    )?._container,
  );

/** False on the server and while hydrating, then follows the OS setting. */
function useShouldReduceMotion(): ComputedRef<boolean> {
  const setting = useReducedMotionSetting();
  const prefersReduced = ref(
    appMounted() && window.matchMedia(REDUCED_MOTION_QUERY).matches,
  );
  let query: MediaQueryList | undefined;
  const update = () => {
    prefersReduced.value = query?.matches ?? false;
  };
  onMounted(() => {
    query = window.matchMedia(REDUCED_MOTION_QUERY);
    update();
    query.addEventListener('change', update);
  });
  onBeforeUnmount(() => query?.removeEventListener('change', update));
  return computed(() => {
    if (setting.value === 'never') return false;
    return setting.value === 'always' || prefersReduced.value;
  });
}

const RemountOnReduce = defineComponent({
  name: 'RemountOnReduce',
  setup(_, { slots }) {
    const reduce = useShouldReduceMotion();
    return () =>
      h(Fragment, { key: reduce.value ? 'reduce' : 'full' }, slots.default?.());
  },
});

